let mediaResources: any = []

// 根据当前的系统时间选择合适的src值，src.day 对应6AM以后， src.dusk 对应 4PM以后 src.night 对应 10PM以后
// const currentHour = new Date().getHours();
const currentHour = Math.random() * 24

// 时间段判断逻辑
if (currentHour >= 22) {
    // 22:00 (10PM) 以后为夜晚
    mediaResources = src.night;
} else if (currentHour >= 16) {
    // 16:00 (4PM) 以后为黄昏
    mediaResources = src.dusk;
} else if (currentHour >= 6) {
    // 6:00 (6AM) 以后为白天
    mediaResources = src.day;
} else {
    // 0:00 - 5:59 为夜晚（凌晨）
    mediaResources = src.night;
}

export { mediaResources }
